    std::map<std::pair<std::uint16_t,std::uint16_t>,
        std::pair<std::vector<std::uint16_t>,std::vector<std::uint16_t>>> invitation_audiences_;
    bool invite_name_locked(std::uint32_t caller,const std::u16string& requested,std::uint64_t now){
        if(!players_.contains(caller)||caller>65535||requested.empty()||requested.size()>19)return false;
        auto folded=[](std::u16string value){for(auto& c:value)if(c>=u'A'&&c<=u'Z')c+=u'a'-u'A';return value;};
        const auto name=folded(requested);std::uint16_t target=0;
        for(const auto& [id,player]:players_)if(id!=caller&&folded(character_name_to_utf16(player.name))==name){
            if(target)return false; // ambiguous development/imported names
            target=static_cast<std::uint16_t>(id);
        }
        if(!target||players_.at(caller).team_token!=players_.at(target).team_token)return false;
        const auto before=parties_.invitations();
        const bool accepted=parties_.invite(static_cast<std::uint16_t>(caller),target,now);
        party_changes(before,false);return accepted;
    }
    void party_send(std::uint32_t caller,const std::vector<Packet>& packets){
        const auto group=caller<=65535?parties_.group(static_cast<std::uint16_t>(caller)):0;
        if(!group)return;
        for(auto member:parties_.members(group))players_.at(member).outbox->enqueue(packets);
    }
    void party_changes(const std::vector<party::State::Invitation>& before,bool rosters){
        const auto after=parties_.invitations();
        auto notification=[&](std::uint16_t group,unsigned opcode,std::uint16_t target){
            if(!parties_.contains(group))return;
            Packet packet;u16(packet,static_cast<std::uint16_t>(opcode));u16(packet,target);
            for(auto member:parties_.members(group))players_.at(member).outbox->enqueue({packet});
        };
        for(const auto& invite:before){
            const bool remains=std::any_of(after.begin(),after.end(),[&](const auto& i){return i.from==invite.from&&i.to==invite.to;});
            if(!remains){
                auto audience=invitation_audiences_.find({invite.from,invite.to});
                if(audience!=invitation_audiences_.end()){
                    auto clear=[&](const auto& members,unsigned opcode,std::uint16_t target){
                        Packet packet;u16(packet,static_cast<std::uint16_t>(opcode));u16(packet,target);
                        for(auto member:members)if(auto player=players_.find(member);player!=players_.end())
                            player->second.outbox->enqueue({packet});
                    };
                    clear(audience->second.first,453,invite.to);
                    clear(audience->second.second,454,invite.from);
                    invitation_audiences_.erase(audience);
                }
            }
        }
        for(const auto& invite:after){
            const bool existed=std::any_of(before.begin(),before.end(),[&](const auto& i){return i.from==invite.from&&i.to==invite.to;});
            if(existed)continue;
            invitation_audiences_[{invite.from,invite.to}]={parties_.members(invite.from),parties_.members(invite.to)};
            // Invitation UI resolves both parties; publish their descriptions
            // without changing the recipient's selected party.
            for(auto pair:{std::pair{invite.from,invite.to},std::pair{invite.to,invite.from}}){
                const auto& members=parties_.members(pair.second);
                auto description=party::roster(pair.second,members,members.front());description.pop_back();
                for(auto member:parties_.members(pair.first))players_.at(member).outbox->enqueue(description);
            }
            notification(invite.from,451,invite.to);notification(invite.to,452,invite.from);
        }
        if(rosters)for(auto& [id,player]:players_){
            const auto group=parties_.group(static_cast<std::uint16_t>(id));
            if(!group)continue;
            auto packets=party::roster(group,parties_.members(group),static_cast<std::uint16_t>(id));
            for(auto member:parties_.members(group))packets.push_back(party::ready(group,member,players_.at(member).ready));
            player.outbox->enqueue(std::move(packets));
        }
    }
