    bool valid_quest_corpse_locked(skills::effects::Scope owner,unsigned quest,unsigned cycle,skills::effects::Scope corpse)const{
        const auto player=players_.find(owner.actor),owned_player=players_.find(corpse.actor);
        const auto live=npc_combat_.find(corpse.actor);
        const auto assignment=quest_npc_owners_.find(corpse.actor);
        if(!quest||!cycle||player==players_.end()||player->second.effect_scope!=owner||owned_player!=players_.end()||live==npc_combat_.end()||assignment==quest_npc_owners_.end()||assignment->second!=std::pair{owner,quest})return false;
        const auto attempt=player->second.quest_kills.find(quest);
        const auto staged=player->second.quest_corpses.find(quest);
        if(attempt==player->second.quest_kills.end()?(staged==player->second.quest_corpses.end()||staged->second.cycle()!=cycle):attempt->second.cycle!=cycle)return false;
        const auto life=live->second.lifetime();const auto* actor=live->second.actor(life);
        return corpse==skills::effects::Scope{instance_scope_,corpse.actor,life.actor_generation}&&actor&&actor->health&&actor->health->current==0;
    }
