    bool npc_empathy_reaction_locked(skills::effects::Scope attacker,combat::npcs::LiveActor& live,const Npc& npc,std::uint64_t now){
        const auto credit=npc_empathy_credit_.find(attacker);
        if(credit==npc_empathy_credit_.end())return true;
        const auto caster=players_.find(credit->second.actor);
        if(caster==players_.end()||caster->second.effect_scope!=credit->second)return true;
        if(next_npc_attack_event_==UINT64_MAX)return false;
        const auto old_effects=live.actor(live.lifetime())->effects;
        const auto hit=live.empathy_attack(live.lifetime(),next_npc_attack_event_++,now);
        if(old_effects!=live.actor(live.lifetime())->effects)for(auto&[id,peer]:players_)peer.outbox->enqueue({emotes::effects_2022(attacker.actor,live.actor(live.lifetime())->effects)});
        if(hit){for(auto&[id,peer]:players_)peer.outbox->enqueue(combat::damage_packets_2022(caster->first,*hit));
            if(hit->killed){record_npc_death_locked(caster->second,npc,live,now);return false;}}
        return true;
    }
