                retire_splinter_scope_locked(retired);dagger_family_commit_watermark_.erase(retired);retire_dagger_paid_owner_draft_locked(retired);attack_outcomes_.erase(retired);charged_weapon_spells_.erase(retired);price_failure_credit_.erase(actor);blurred_vision_credit_.erase(actor);panic_credit_.erase(actor);mind_wrack_credit_.erase(actor);fevered_credit_.erase(actor);panic_events_.erase(retired);
                std::erase_if(resolved_attacks_,[&](const auto& event){return event.attacker==retired;});
