            std::erase_if(npc_empathy_credit_,[&](const auto& entry){return entry.first.actor==actor;});
            std::erase_if(elemental_projectiles_,[&](const auto& shot){return shot.target.actor==actor;});
            std::erase_if(spear_light_projectiles_,[&](const auto& shot){return shot.target.actor==actor||shot.caster.actor==actor;});
            std::erase_if(lightning_projectiles_,[&](const auto& shot){return shot.target.actor==actor;});
