    void record_npc_death_locked(Player* source,const Npc& npc,combat::npcs::LiveActor& live,std::uint64_t now){
        const skills::effects::Scope target{instance_scope_,npc.id,live.lifetime().actor_generation};
        retire_npc_patrol_locked(target);
        retire_mending_actor_locked(target,now);
        if(const auto link=putrid_bile_links_.lookup(target)){
            const auto hex=live.hex_effect(live.lifetime(),link->effect);
            if(const auto owned=putrid_bile_links_.take_death(target,now);
               owned&&hex&&hex->skill==2058&&hex->cause==link->caster.actor&&
               hex->rank==link->rank&&hex->expires&&now<*hex->expires)
                putrid_bile_death_locked(*owned,npc.plane,npc.x,npc.y,now);
        }
        retire_bonds_caster_locked(target,now);
        if(const auto ended=live.retire_weapon_spell(live.lifetime(),now))for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(target.actor,ended->instance),emotes::effects_2022(target.actor,live.actor(live.lifetime())->effects)});
        std::erase_if(spear_light_projectiles_,[&](const auto& shot){return shot.target==target||shot.caster==target;});
        retire_energy_hex_target_locked(target,now);
        end_parasitic_target_locked(target,now);
        clear_life_drains_locked(target,now);
        // Renewal has no death reward. Retire its exact owned record now so
        // clients do not retain the enchantment until the next World tick.
        if(const auto effects=live.owned_effect_snapshot(live.lifetime()))
            for(const auto& effect:effects->active(target,now))
                if(effect.skill==181||effect.skill==2860)
                    remove_npc_enchantment_locked(live,live.lifetime(),effect.instance,now);
        if(source)source->npc_deaths.push_back({target,npc.combat_definition->binding,npc.captured_name,now,{npc.x,npc.y,npc.plane}});
        for(auto& [player_id,player]:players_)
            for(auto& [quest,objective]:player.quest_kills)
                if((!objective.timed||objective.timed->death(player.effect_scope,objective.cycle,target,now))&&objective.remaining.erase(target)){
                    if(objective.required){
                        const auto killed=objective.assigned.size()-objective.remaining.size();
                        if(objective.restored_credits+killed<=objective.required)
                            objective.pending_credits.try_emplace(objective.credit_ids.at(target),now);
                    }else if(objective.any_death)objective.remaining.clear();
                }
        for(auto& [player_id,player]:players_)for(auto&[quest,objective]:player.quest_corpses)
            objective.death(player.effect_scope,objective.cycle(),target);
        for(auto& [player_id,player]:players_)for(auto&[quest,objective]:player.quest_escorts)
            objective.death(player.effect_scope,objective.cycle(),target);
        for(auto& [player_id,player]:players_)
            for(auto& [quest,objective]:player.quest_waves)
                objective.death(player.effect_scope,objective.cycle(),target);
    }
    void resolve_controlled_spirit_projectiles_locked(std::uint64_t at){
        for(std::size_t i=0;i<controlled_spirit_projectiles_.size();){
            if(controlled_spirit_projectiles_[i].arrives>at){++i;continue;}
            const auto shot=controlled_spirit_projectiles_[i];
            controlled_spirit_projectiles_.erase(controlled_spirit_projectiles_.begin()+i);
            const auto arrival=skills::effects::spirits::attack_arrival_2022(
                shot.spirit.actor,shot.synchronization);
            for(auto& [id,peer]:players_)if(peer.npc_publication_ready)peer.outbox->enqueue({arrival});
            const auto owner=players_.find(shot.owner.actor);
            const auto placed=npcs_.find(shot.target.actor);
            const auto live=npc_combat_.find(shot.target.actor);
            if(owner==players_.end()||owner->second.effect_scope!=shot.owner||
               placed==npcs_.end()||live==npc_combat_.end()||live->second.hex_scope()!=shot.target||
               placed->second.plane!=shot.plane||
               !live->second.hostile_to_players(live->second.lifetime()))continue;
            const auto* actor=live->second.actor(live->second.lifetime());
            if(!actor||!actor->damageable||!actor->health||actor->health->current<=0)continue;
            if(navigation_){
                const navigation::Point from{shot.from_x,shot.from_y};
                const navigation::Point to{placed->second.x,placed->second.y};
                const auto cell=navigation_->locate_cell(shot.plane,from);
                if(!cell)continue;
                const auto reached=layered_->trace({shot.plane,*cell},from,to);
                if(!reached||reached->plane!=shot.plane)continue;
            }
            // A released shot keeps its captured spirit identity after summon
            // expiry. Owner departure retires it; owner death does not rewind
            // an already released flight. Settle recipient events before
            // quoting conversion, then reacquire scopes after those callbacks.
            advance_npc_conditions_locked(shot.target.actor,live->second,at);
            const auto current=npc_combat_.find(shot.target.actor);
            const auto position=npcs_.find(shot.target.actor);
            const auto credited=players_.find(shot.owner.actor);
            if(current==npc_combat_.end()||position==npcs_.end()||
               current->second.hex_scope()!=shot.target||credited==players_.end()||
               credited->second.effect_scope!=shot.owner)continue;
            commit_npc_reversal_or_damage_locked(credited->second,position->second,current->second,
                {combat::Kind::armor_ignoring,double(shot.damage),shot.level,shot.attack_skill},at);
        }
    }
