    std::vector<std::uint64_t> reactive_seed_deadlines_locked(const Player& p,std::uint64_t limit)const{
        std::vector<std::uint64_t> deadlines;
        for(const auto& event:skills::effects::expired_condition_transitions(p.conditions,p.health_updated,limit))
            deadlines.push_back(event.at);
        // These owned endings create a condition and can therefore trigger
        // Fragility/Seed just as an already-active condition's loss can.
        for(const auto& [id,entry]:p.health_effects)
            if(entry.expires&&*entry.expires>p.health_updated&&*entry.expires<=limit&&
               (entry.skill==44||entry.skill==2054||skills::effects::illusion_haste(entry.skill,entry.rank)))
                deadlines.push_back(*entry.expires);
        std::sort(deadlines.begin(),deadlines.end());deadlines.erase(std::unique(deadlines.begin(),deadlines.end()),deadlines.end());
        return deadlines;
    }
    std::optional<std::uint64_t> next_reactive_seed_deadline_locked(std::uint64_t limit)const{
        std::optional<std::uint64_t> next;
        for(const auto& [id,credit]:fragility_credit_){
            const auto found=players_.find(id);if(found==players_.end())continue;const auto& p=found->second;
            if(credit.target!=p.effect_scope||!p.resources||p.precise_health<=0||!p.effect_registry||p.health_updated>=limit)continue;
            for(const auto at:reactive_seed_deadlines_locked(p,limit)){
                const auto hex=p.effect_registry->newest_skill(p.effect_scope,19,at,2998);
                if(!hex||hex->instance!=credit.effect||!p.effect_registry->newest_skill(p.effect_scope,274,at))continue;
                if(!next||at<*next)next=at;
            }
        }
        return next;
    }
    bool dispatch_reactive_seed_deadlines_locked(std::uint64_t at){
        std::vector<skills::effects::Scope> pending;
        for(const auto& [id,credit]:fragility_credit_){
            const auto found=players_.find(id);if(found==players_.end())continue;const auto& p=found->second;
            if(credit.target!=p.effect_scope||!p.resources||p.precise_health<=0||!p.effect_registry||p.health_updated>=at)continue;
            const auto hex=p.effect_registry->newest_skill(p.effect_scope,19,at,2998);
            if(!hex||hex->instance!=credit.effect||!p.effect_registry->newest_skill(p.effect_scope,274,at))continue;
            const auto deadlines=reactive_seed_deadlines_locked(p,at);
            if(std::find(deadlines.begin(),deadlines.end(),at)!=deadlines.end())pending.push_back(p.effect_scope);
        }
        // These expiries can heal another actor. Drain them before any actor's
        // Health integration may pass their shared historical boundary.
        for(const auto scope:pending){const auto found=players_.find(scope.actor);
            if(found!=players_.end()&&found->second.effect_scope==scope&&found->second.health_updated<at&&
               !advance_health_locked(found->second,at))return false;
        }
        return true;
    }
    std::optional<std::uint64_t> timed_effect_boundary_;
    bool settle_timed_effects_locked(std::uint64_t now){
        // Reentry may integrate a recipient at the active event, but may not
        // pull any other actor beyond it. The outer drain owns continuation.
        if(timed_effect_boundary_)return now<=*timed_effect_boundary_;
        struct Reset {std::optional<std::uint64_t>& boundary;~Reset(){boundary.reset();}} reset{timed_effect_boundary_};
        for(unsigned work=0;work<65536;++work){
            auto boundary=now;
            for(const auto deadline:{next_spirit_rift_locked(),glimmering_marks_.next_deadline(),damage_fields_.next_deadline(),lightning_strikes_.next_deadline(),
                    lightning_surges_.next_deadline(),parasitic_bonds_.next_deadline(),next_fevered_deadline_locked(now),next_reactive_seed_deadline_locked(now),next_ordinary_dagger_second_followon_locked(),next_timed_projectile_locked(),next_npc_watchful_deadline_locked(),next_npc_phantasm_deadline_locked(),next_npc_bonds_deadline_locked(),next_npc_self_enchantment_deadline_locked(),next_npc_friendly_heal_deadline_locked(),next_npc_reversal_deadline_locked(),next_npc_imbue_deadline_locked(),next_putrid_death_locked()})
                if(deadline)boundary=std::min(boundary,*deadline);
            if(parasitic_bonds_.size()){
                for(const auto scope:parasitic_bonds_.participants()){
                    const auto player=players_.find(scope.actor);
                    if(player!=players_.end()&&player->second.effect_scope==scope)
                        boundary=std::min(boundary,next_parasitic_health_boundary_locked(player->second,boundary));
                }
                const auto forecast=skills::effects::forecast_parasitic_npcs(parasitic_bonds_.pending(),boundary,
                    [&](auto scope)->std::optional<combat::npcs::LiveActor>{
                        const auto live=npc_combat_.find(scope.actor);
                        return live==npc_combat_.end()?std::nullopt:std::optional(live->second);
                    });
                if(forecast.reason!=skills::effects::BondForecastReason::okay)return false;
                if(forecast.next)boundary=std::min(boundary,forecast.next->at);
            }
            std::vector<MendingRangeEnd> mending_ranges;
            for(unsigned refine=0;;++refine){
                const auto before=boundary;mending_ranges.clear();
                if(!mending_boundary_locked(boundary,now,mending_ranges)||!energy_hex_boundary_locked(boundary)||
                   !putrid_health_boundary_locked(boundary))return false;
                if(boundary==before)break;
                if(refine==65535)return false;
            }
            if(!timed_projectile_facts_ready_locked(boundary))return false;
            timed_effect_boundary_=boundary;
            if(!dispatch_putrid_health_locked(boundary))return false;
            const auto deliveries_before=timed_delivery_count_locked();const auto releases_before=timed_delivery_releases_;
            // Equal-time provider order is explicit private-server policy.
            // Each queue consumes its own records before reactive callbacks.
            if(!dispatch_mending_resources_locked(boundary,mending_ranges))return false;
            if(!dispatch_energy_hex_resources_locked(boundary))return false;
            dispatch_lightning_strikes_locked(boundary);
            dispatch_damage_fields_locked(boundary);
            dispatch_glimmering_marks_locked(boundary);
            dispatch_spirit_rift_locked(boundary);
            if(!dispatch_fevered_deadlines_locked(boundary))return false;
            if(!dispatch_reactive_seed_deadlines_locked(boundary))return false;
            dispatch_parasitic_returns_locked(boundary);
            resolve_projectiles_locked(boundary);
            resolve_disrupting_daggers_locked(boundary);
            resolve_lightning_projectiles_locked(boundary);
            resolve_water_projectiles_locked(boundary);
            resolve_elemental_projectiles_locked(boundary);
            resolve_spear_light_locked(boundary);
            resolve_stone_projectiles_locked(boundary);
            resolve_javelins_locked(boundary);
            resolve_deathly_swarms_locked(boundary);
            resolve_ordinary_projectiles_locked(boundary);
            resolve_ordinary_dagger_seconds_followon_locked(boundary);
            resolve_controlled_spirit_projectiles_locked(boundary);
            resolve_npc_deliveries_locked(boundary);
            if(!dispatch_npc_watchful_locked(boundary))return false;
            if(!dispatch_npc_phantasm_locked(boundary))return false;
            if(!dispatch_npc_bonds_locked(boundary))return false;
            if(!dispatch_npc_self_enchantment_locked(boundary))return false;
            if(!dispatch_npc_friendly_heals_locked(boundary))return false;
            if(!dispatch_npc_reversal_locked(boundary))return false;
            if(!dispatch_npc_imbue_locked(boundary))return false;
            if(!dispatch_putrid_deaths_locked(boundary))return false;
            if(const auto next=next_timed_projectile_locked();next&&*next<=boundary){
                if(deliveries_before==timed_delivery_count_locked()&&releases_before==timed_delivery_releases_)return false;
                continue;
            }
            if(boundary==now){expire_defensive_wards_locked(now);expire_elemental_wards_locked(now);expire_melee_wards_locked(now);expire_foes_wards_locked(now);return true;}
        }
        return false; // Retain pending work rather than skipping its frontier.
    }
