        if(!target||!effect.instance||effect.skill!=1411||effect.cause!=target||effect.expires||
           !skills::effects::stamina_signet(effect.rank))throw std::invalid_argument("invalid Stamina status");
        Packet packet;u16(packet,64);u32(packet,target);u32(packet,0);
