    void health_event_locked(Player& player,double delta,std::uint64_t now,bool healing=false){
        const bool pending=player.deep_wound.debt!=0;
        const auto multiplier=healing&&delta>0&&player.effect_registry?skills::effects::healing_hex_multiplier(player.effect_registry->active(player.effect_scope,now),now):1.;
        player.deep_wound.event(player.precise_health,delta,healing,multiplier);
        settle_conditional_stance_locked(player,now);
        player.resources->health=static_cast<unsigned>(std::ceil(player.precise_health));
        if(pending&&delta!=0)publish_health_locked(player);
    }
    void commit_applications_locked(skills::effects::Scope scope,std::uint64_t now){
        const auto player=players_.find(scope.actor),caster_end=players_.end();
        const auto victim=npc_combat_.find(scope.actor);const auto npc=npcs_.find(scope.actor);
        std::vector<skills::effects::ApplicationEvent> events;
        if(player!=players_.end()){
            if(player->second.effect_scope!=scope||!player->second.effect_registry)return;
            events=player->second.effect_registry->take_applications(scope);
        }else{
            if(victim==npc_combat_.end()||npc==npcs_.end()||victim->second.hex_scope()!=scope)return;
            events=victim->second.take_applications(victim->second.lifetime());
        }
        for(const auto& event:events){
            auto& cursor=application_cursors_[scope.actor];
            if(event.target!=scope||(cursor.actor==scope&&event.sequence<=cursor.event))continue;
            cursor={scope,event.sequence,event.applied.applied};
            if(player!=players_.end()){
                auto& p=player->second;
                if(const auto ended=skills::effects::natural_stride_application(*p.effect_registry,scope,event)){
                    p.movement_effects.remove(ended->instance,now);advance_movement_effects_locked(p,now);
                    for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(scope.actor,ended->instance)});
                }
            }
            if(player==players_.end())if(const auto ended=victim->second.natural_stride_application(victim->second.lifetime(),event,now)){
                for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(scope.actor,ended->instance)});
                refresh_npc_movement_locked(scope.actor,now);
            }
            for(const auto& observer:event.observers){
                if(observer.skill!=100)continue;
                const auto plan=skills::effects::soul_barbs(observer.rank);
                const auto credit=soul_barbs_credit_.find(scope.actor);
                if(!plan||credit==soul_barbs_credit_.end()||credit->second.target!=scope||credit->second.effect!=observer.instance)continue;
                const auto caster=players_.find(credit->second.caster.actor);
                const bool attribution=caster!=caster_end&&caster->second.effect_scope==credit->second.caster;
                const combat::Damage damage{combat::Kind::armor_ignoring,double(plan->damage),credit->second.level,100};
                // Damage/death may retire observer ownership. Retain only its
                // scoped attribution, not a map iterator across those reactions.
                const auto original=credit->second;
                if(player!=players_.end()){
                    auto& p=player->second;if(!p.resources||p.precise_health<=0)continue;
                    now=std::max(now,p.health_updated);if(!advance_health_locked(p,now)||p.precise_health<=0)continue;
                    auto actor=incoming_spell_actor_locked(p,{p.id,p.effect_scope.generation,
                        combat::Health{p.precise_health,p.resources->max_health},{},p.effects,true},now);
                    const auto hit=combat::apply(actor,damage,true);if(hit.reason!=combat::Reason::accepted)continue;
                    commit_player_reactive_hit_locked(p,hit,
                        attribution?std::optional<unsigned>(original.caster.actor):std::nullopt,now);
                }else{
                    auto& live=victim->second;now=std::max(now,live.health_clock(live.lifetime()).value_or(now));
                    advance_npc_conditions_locked(scope.actor,live,now);
                    commit_npc_reversal_or_damage_locked(attribution?&caster->second:nullptr,npc->second,live,damage,now);
                }
            }
        }
    }
