    void settle_arcane_returns_locked(std::uint64_t now){
        for(const auto& link:arcane_returns_.pending()){
            if(now<link.applied)continue;
            const auto caster=players_.find(link.caster.actor);
            if(caster==players_.end()||caster->second.effect_scope!=link.caster){arcane_returns_.discard(link.caster);continue;}
            bool present=false;
            if(const auto target=players_.find(link.target.actor);target!=players_.end()){
                if(target->second.effect_scope!=link.target){arcane_returns_.discard(link.target);continue;}
                present=target->second.effect_registry&&bool(target->second.effect_registry->lookup(link.target,link.effect));
            }else if(const auto target=npc_combat_.find(link.target.actor);target!=npc_combat_.end()){
                if(link.target!=skills::effects::Scope{instance_scope_,link.target.actor,target->second.lifetime().actor_generation}){arcane_returns_.discard(link.target);continue;}
                present=bool(target->second.hex_effect(target->second.lifetime(),link.effect));
            }else {arcane_returns_.discard(link.target);continue;}
            if(present&&now<link.expires)continue;
            auto& source=caster->second;
            // A return discovered while another actor is integrating Health
            // waits for its caster's end effects. Do not recursively integrate
            // the caster from this removal callback or move Energy past them.
            if(!source.resources||source.health_updated!=now||now<source.energy_updated)continue;
            const auto reward=arcane_returns_.end(link.target,link.effect,now,true);if(!reward)continue;
            if(source.energy_updated)regenerate_energy_locked(source,now-source.energy_updated);
            source.energy_updated=now;
            gain_energy_locked(source,reward->energy, now);
            source.outbox->enqueue(owner_vitals(source));
        }
    }
    static int survival_pips_locked(const Player& player,std::uint64_t at){
        return player.effect_registry?skills::effects::survival_pips(*player.effect_registry,player.effect_scope,player.conditions.count(at),at)+
            (player.weapon_spell?int(skills::effects::weapon_spell_pips(*player.weapon_spell,*player.effect_registry,player.effect_scope,player.conditions,at)):0):0;
    }
    static std::uint64_t health_crossing_end(std::uint64_t starts,std::uint64_t limit,double health,int pips){
        if(const auto crossing=combat::health_timing::death_delay(health,pips);crossing&&*crossing<limit-starts)return starts+*crossing;
        return limit;
    }
    std::uint64_t next_parasitic_health_boundary_locked(Player& player,std::uint64_t limit,int well_pips=0){
        const auto starts=player.health_updated;if(starts>=limit||!player.resources)return limit;
        auto end=limit;
        for(auto at:player.conditions.expiry_boundaries(starts,limit))end=std::min(end,at);
        if(player.health_regeneration)for(auto at:player.health_regeneration->expiry_boundaries(starts,limit))end=std::min(end,at);
        const int external=player.conditions.degeneration_pips(starts)+(player.health_regeneration?player.health_regeneration->pips(starts):0)+survival_pips_locked(player,starts)+well_pips;
        if(recovery_schedule_&&!player.passive_recovery)player.passive_recovery.emplace(*recovery_schedule_,starts);
        unsigned automatic=0;
        if(player.passive_recovery){
            // advance_health inhibits automatic recovery before integrating an
            // externally degenerating segment;predict that same policy.
            if(external>=0&&player.precise_health>0)automatic=player.passive_recovery->pips(starts);
            for(const auto& segment:player.passive_recovery->segments(limit))if(segment.end>starts){end=std::min(end,segment.end);break;}
        }
        return health_crossing_end(starts,end,player.precise_health,std::clamp(external+static_cast<int>(automatic),-10,10));
    }
    void deliver_parasitic_return_locked(const skills::effects::ParasiticBonds::Return& returned){
        const auto caster=players_.find(returned.caster.actor);
        if(caster==players_.end()||caster->second.effect_scope!=returned.caster||!caster->second.resources)return;
        auto& source=caster->second;
        if(!advance_health_locked(source,returned.at)||source.precise_health<=0)return;
        health_event_locked(source,returned.healing,returned.at,true);publish_health_locked(source);
        if(source.precise_health<=0)kill_locked(source,returned.at);
    }
    void end_parasitic_target_locked(skills::effects::Scope target,std::uint64_t now){
        // Callbacks can kill a caster and cancel other pending links. Resolve
        // each saved identity against the live ledger before delivering it.
        for(const auto& link:parasitic_bonds_.pending())if(link.target==target)
            if(const auto returned=parasitic_bonds_.end(target,link.effect,now,true))deliver_parasitic_return_locked(*returned);
    }
    void dispatch_parasitic_returns_locked(std::uint64_t now){
        if(settling_parasitic_returns_||!parasitic_bonds_.size())return;
        struct Guard{bool& flag;explicit Guard(bool& f):flag(f){flag=true;}~Guard(){flag=false;}} guard(settling_parasitic_returns_);
        for(;;){
            const auto deadline=parasitic_bonds_.next_deadline();if(!deadline)break;
            auto horizon=std::min(now,*deadline);
            if(const auto pulse=damage_fields_.next_deadline())horizon=std::min(horizon,*pulse);
            if(const auto rift=next_spirit_rift_locked())horizon=std::min(horizon,*rift);
            const auto participants=parasitic_bonds_.participants();
            // A death/condition/end-heal boundary can change another actor's
            // incoming hexes. Stop every participant at the earliest
            // such event rather than advancing in numeric actor order.
            for(const auto scope:participants){
                const auto caster=players_.find(scope.actor);
                if(caster!=players_.end()&&caster->second.effect_scope==scope)
                    horizon=std::min(horizon,next_parasitic_health_boundary_locked(caster->second,horizon));
            }
            const auto links=parasitic_bonds_.pending();
            const auto forecast=skills::effects::forecast_parasitic_npcs(links,horizon,[&](auto scope)->std::optional<combat::npcs::LiveActor>{
                const auto npc=npc_combat_.find(scope.actor);
                return npc==npc_combat_.end()?std::nullopt:std::optional(npc->second);
            });
            if(forecast.reason!=skills::effects::BondForecastReason::okay)throw std::logic_error("Parasitic Bond NPC timeline invariant");
            if(forecast.next)horizon=std::min(horizon,forecast.next->at);
            // Retain outgoing links while their casters advance: an earlier
            // degeneration death must remove the hex before natural expiry.
            // Prepare even before an expiry is due,so recipient ID order does
            // not let it advance beyond its caster's death first.
            for(const auto scope:participants){
                const auto caster=players_.find(scope.actor);
                if(caster!=players_.end()&&caster->second.effect_scope==scope)
                    advance_health_locked(caster->second,horizon);
            }
            for(const auto scope:participants){
                const auto npc=npc_combat_.find(scope.actor);
                if(npc!=npc_combat_.end()&&npc->second.hex_scope()==scope)advance_npc_conditions_locked(scope.actor,npc->second,horizon);
            }
            settle_damage_fields_locked(horizon);
            parasitic_bonds_.dispatch_due(horizon,[&](const auto& returned){deliver_parasitic_return_locked(returned);});
            if(horizon==now)break;
        }
    }
    void clear_parasitic_caster_locked(skills::effects::Scope scope,std::uint64_t now){
        const auto cancelled=parasitic_bonds_.take_caster(scope);
        for(const auto& link:cancelled){
            const auto victim=players_.find(link.target.actor);
            if(victim==players_.end()){
                const auto npc=npc_combat_.find(link.target.actor);
                if(npc!=npc_combat_.end()&&npc->second.hex_scope()==link.target){
                    advance_npc_conditions_locked(link.target.actor,npc->second,now);
                    if(npc->second.remove_hex_effect(npc->second.lifetime(),link.effect,now))
                        for(auto&[id,peer]:players_)peer.outbox->enqueue({emotes::effects_2022(link.target.actor,npc->second.actor(npc->second.lifetime())->effects)});
                }
                continue;
            }
            if(victim->second.effect_scope!=link.target)continue;
            auto& target=victim->second;const auto at=std::max(now,target.health_updated);
            advance_health_locked(target,at);
            if(target.health_effects.contains(link.effect))remove_health_effect_locked(target,link.effect,at);
        }
    }
    // A resource event cannot cross timed Health/enchantment ends and then
    // settle them retroactively. Keep this opt-in boundary explicit while
