            // reference and even the numeric ID cannot establish current authority.
            const auto found=npc_combat_.find(scope.actor);
            if(found==npc_combat_.end()||found->second.hex_scope()!=scope)return true;
            current=&found->second;const auto actor=current->actor(life);
