            const auto credit=attack_hex_credit_.find({player.id,skill});
            const auto original=credit==attack_hex_credit_.end()?std::optional<BackfireCredit>{}:credit->second;
            if(reaction->plan.consume)remove_health_effect_locked(player,reaction->cause.instance,now);
            if(!original||original->target!=player.effect_scope||original->effect!=reaction->cause.instance)continue;
            if(reaction->plan.energy_loss){
                if(now<player.energy_updated)return false;
                if(player.energy_updated)regenerate_energy_locked(player,now-player.energy_updated);
                player.energy_updated=now;const auto before=mind_wrack_energy_locked(player);
                drain_energy_locked(player,reaction->plan.energy_loss,now);
                player.outbox->enqueue(owner_vitals(player));observe_mind_wrack_energy_locked(player,before,now);if(player.precise_health<=0)return false;continue;
            }
