    skills::ranger::ReadTheWind bow_preparation_locked(const Player& player,std::uint64_t now)const{
        skills::ranger::ReadTheWind result;
        if(player.effect_registry)for(const auto& effect:player.effect_registry->active(player.effect_scope,now))
            if(effect.skill==432&&effect.expires&&effect.applied<=now&&*effect.expires-effect.applied==24000)
                result.prepare(effect.rank,effect.applied);
        return result;
    }
    std::optional<skills::ranger::IgniteArrowsPlan> bow_ignite_locked(const Player& player,std::uint64_t now)const{
        if(!player.effect_registry)return {};
        const auto effect=player.effect_registry->newest_skill(player.effect_scope,431,now);
        if(!effect||!effect->expires||*effect->expires-effect->applied!=24000)return {};
        return skills::ranger::ignite_arrows(effect->rank);
    }
    std::optional<skills::effects::Entry> owned_reactive_hex_locked(skills::effects::Scope target,const BackfireCredit& credit,unsigned skill,std::uint64_t now)const{
        if(credit.target!=target||!credit.effect)return {};
        std::optional<skills::effects::Entry> entry;
        const auto player=players_.find(target.actor);
        if(player!=players_.end()){
            if(player->second.effect_scope!=target||!player->second.effect_registry)return {};
            entry=player->second.effect_registry->lookup(target,credit.effect);
        }else{
            const auto npc=npc_combat_.find(target.actor);
            if(npc==npc_combat_.end()||npc->second.hex_scope()!=target)return {};
            entry=npc->second.hex_effect(npc->second.lifetime(),credit.effect);
        }
        if(!entry||entry->skill!=skill||entry->cause!=credit.caster.actor||entry->kind!=skills::effects::Category::hex||
           entry->applied>now||!entry->expires||now>=*entry->expires)return {};
        return entry;
    }
    void reactive_hex_damage_locked(skills::effects::Scope target,const BackfireCredit& credit,unsigned skill,unsigned damage,std::uint64_t now){
        if(credit.target!=target)return;
        const auto source=players_.find(credit.caster.actor);
        if(source==players_.end()||source->second.effect_scope!=credit.caster)return;
        const combat::Damage incoming{combat::Kind::armor_ignoring,double(damage),credit.level,skill};
        const auto player=players_.find(target.actor);
        if(player!=players_.end()){
            auto& victim=player->second;
            if(victim.effect_scope!=target||!victim.resources||victim.precise_health<=0)return;
            auto actor=incoming_spell_actor_locked(victim,{victim.id,target.generation,combat::Health{victim.precise_health,victim.resources->max_health},{},victim.effects,true},now);
            const auto hit=combat::apply(actor,incoming,true);if(hit.reason!=combat::Reason::accepted)return;
            if(!preflight_player_reversal_locked(victim,hit,now))return;
            commit_player_reactive_hit_locked(victim,hit,source->first,now);
        }else{
            const auto live=npc_combat_.find(target.actor);const auto npc=npcs_.find(target.actor);
            if(live==npc_combat_.end()||npc==npcs_.end()||live->second.hex_scope()!=target)return;
            advance_npc_conditions_locked(target.actor,live->second,now);
            const auto foe=player_npc_attack_relation_locked(source->second,live->second);if(!foe||!*foe)return;
            commit_npc_reversal_or_damage_locked(source->second,npc->second,live->second,incoming,now,nullptr,nullptr,nullptr,false,{},nullptr,!live->second.hostile_to_players(live->second.lifetime()));
        }
    }
