    std::optional<skills::effects::AttributedBlock> player_attributed_block_contact_locked(Player& defender,std::uint64_t now,bool unblockable=false,unsigned attack_skill=0,bool melee=false){
        if(!defender.effect_registry||!shield_stance_locked(defender,now))return {};
        if(defender.effect_registry->newest_skill(defender.effect_scope,363,now)&&now<defender.reviewed_shield_updated)return {};
        if(skills::effects::active_bonetti_defense(*defender.effect_registry,defender.effect_scope,now)&&
           (!advance_resource_event_locked(defender,now)||defender.precise_health<=0))return {};
        const auto distortion=defender.effect_registry->newest_skill(defender.effect_scope,11,now);
        if(distortion&&!preflight_debilitating_locked(defender,2,now))return {};
        const auto warding=defender.weapon_spell?skills::effects::warding_block_entry(*defender.weapon_spell,*defender.effect_registry,defender.effect_scope,now):std::nullopt;
        const auto probability=skills::effects::reviewed_block_probability(defender.effect_registry->active(defender.effect_scope,now),unblockable,now,effective_shield_locked(defender),defender.reviewed_strength,attack_skill,warding);
        if(!probability)return {};
        const auto environmental=melee?ward_melee_source_locked(defender.effect_scope,now):std::nullopt;
        if(unblockable||skills::effects::rigor_mortis_prevents_block(defender.effect_registry->active(defender.effect_scope,now),now)||(*probability==0&&!environmental))return skills::effects::AttributedBlock{AttackOutcome::hit,{},0};
        const double draw=sample_attack_block_locked();
        auto sources=skills::effects::reviewed_block_sources(defender.effect_registry->active(defender.effect_scope,now),now,effective_shield_locked(defender),defender.reviewed_strength,attack_skill,warding);
        if(!sources)return {};
        if(environmental)sources->push_back(*environmental);
        const auto contact=skills::effects::resolve_attributed_block_draw(*sources,draw);
        if(contact&&contact->source&&contact->source->skill==11){
            // Insufficient Energy ends this stance after the successful block.
            // Preserve the sub-cost remainder: retail partial-loss behavior is
            // still an explicit verification gap, not inferred from a tooltip.
            const auto energy=mind_wrack_energy_locked(defender);
            const auto units=(std::int64_t(energy.current)-energy.debt)*overcast::energy_unit+energy.fractional_units;
            if(units<2*overcast::energy_unit){
                defender.effect_registry->remove(defender.effect_scope,contact->source->instance);
                for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(defender.id,contact->source->instance)});
            }else commit_debilitating_locked(defender,2,now);
        }
        return contact;
    }
