    struct BowSelfDisableTransaction {
        skills::effects::Scope owner;combat::weapon::BowSelfDisablePlan plan;
        skills::effects::CooldownBarSnapshot bar;std::uint64_t event=0;
    };
    std::optional<BowSelfDisableTransaction> prepare_bow_self_disable_locked(Player& source,
            const combat::weapon::AttackPlan& attack,std::uint64_t event,std::uint64_t now){
        const auto plan=combat::weapon::bow_self_disable(attack.skill,attack.rank,attack.copy);
        if(!plan||!event||source.precise_health<=0||!source.cooldown_authority||source.cooldown_order_failures||
           now<source.health_updated||now<source.energy_updated)return {};
        const auto bar=source.cooldown_authority->snapshot(source.effect_scope);
        if(!bar||bar->published.at>now)return {};
        auto authority=*source.cooldown_authority;const auto stamp=authority.order(source.effect_scope,now);if(!stamp)return {};
        const auto old=attack_interrupt_disables_.find(source.effect_scope);
        const auto ledger=old==attack_interrupt_disables_.end()?combat::weapon::AttackInterruptDisables(source.effect_scope):old->second;
        if(!ledger.propose_self_hit(source.effect_scope,*plan,*bar,*stamp,event,now))return {};
        return BowSelfDisableTransaction{source.effect_scope,*plan,*bar,event};
    }
    void commit_bow_self_disable_locked(const BowSelfDisableTransaction& transaction,std::uint64_t now){
        const auto found=players_.find(transaction.owner.actor);
        // Retaliation can kill the source after qualifying a landed hit. Never
        // attach a new disable to a retired/reused lifetime or dead source.
        if(found==players_.end()||found->second.effect_scope!=transaction.owner||found->second.precise_health<=0)return;
        auto& source=found->second;
        if(source.cooldown_order_failures)return;
        if(!source.cooldown_authority)throw std::logic_error("preflighted bow self-disable authority lost");
        const auto bar=source.cooldown_authority->snapshot(transaction.owner);
        // All three bar writers (publish_skillbar_transition, temporary copy
        // restoration and configure_adrenaline) acquire this same mutex. No
        // damage/reaction path calls them or invokes a Runtime callback here.
        // This compares within one impact, never against the release-time bar.
        if(!bar||*bar!=transaction.bar)throw std::logic_error("bow impact bar changed inside damage transaction");
        auto authority=*source.cooldown_authority;const auto stamp=authority.order(transaction.owner,now);
        const auto old=attack_interrupt_disables_.find(transaction.owner);
        const auto ledger=old==attack_interrupt_disables_.end()?combat::weapon::AttackInterruptDisables(transaction.owner):old->second;
        const auto proposed=stamp?ledger.propose_self_hit(transaction.owner,transaction.plan,*bar,*stamp,transaction.event,now):std::nullopt;
        if(!proposed)throw std::logic_error("preflighted bow self-disable failed");
        attack_interrupt_disables_.insert_or_assign(transaction.owner,*proposed);*source.cooldown_authority=std::move(authority);
        source.local_cooldown_snapshot_ready=false;
        // Session synchronize_disables composes this independent deadline with
        // its known local recharge before emitting228. World never guesses0.
    }
