    void endurance_hit_locked(const combat::weapon::QualifiedHit& hit,const combat::weapon::Owned& weapon){
        const auto type=weapon.item_type;
        if(type!=2&&type!=15&&type!=27&&type!=32&&type!=35)return;
        const auto found=players_.find(hit.attacker.actor);
        if(found==players_.end()||found->second.effect_scope!=hit.attacker)return;
        auto& p=found->second;
        if(!p.effect_registry||!skills::effects::active_endurance(*p.effect_registry,p.effect_scope,hit.at)||
           !advance_resource_event_locked(p,hit.at)||p.precise_health<=0)return;
        const auto plan=skills::effects::active_endurance(*p.effect_registry,p.effect_scope,hit.at);if(!plan)return;
        // A zero-burden projection curve for non-Overcast players is temporary;
        // its arbitrary nonzero rate is unused and never becomes live state.
        const auto curve=p.overcast_curve?*p.overcast_curve:overcast::CeilingCurve(p.effect_scope,hit.at,1);
        const auto reward=overcast::prepare_gain(curve,p.effect_scope,*p.resources,p.energy_regeneration,p.energy_debt,plan->energy,hit.at,p.energy_pips,p.energy_fractional_tail,plan->ceiling);
        if(!reward)throw std::logic_error("Endurance Energy reward rejected");
        if(p.overcast_curve)commit_overcast_energy_locked(p,reward->state);
        else {p.resources=reward->state.resources;p.energy_regeneration=reward->state.regeneration;p.energy_debt=reward->state.debt;p.energy_fractional_tail=reward->state.fractional_tail;}
        if(reward->gained_units)p.outbox->enqueue(owner_vitals(p));
    }
    void record_hit_locked(Player& p,const combat::Hit& hit,std::uint64_t now,bool armor_respecting=true){
        consume_watch_yourself_hit_locked(p,hit.applied,armor_respecting&&hit.reason==combat::Reason::accepted&&hit.kind!=combat::Kind::armor_ignoring,now);
        record_adrenaline_damage_locked(p,hit.damage,now);
        // A matching damage event still triggers the Mantra when later flat
        // protection absorbs it. It is not an Essence Bond positive-loss test.
        if(hit.reason!=combat::Reason::accepted||!p.resources||!p.effect_registry||now<p.energy_updated)return;
        const auto mantra=skills::effects::active_elemental_mantra(*p.effect_registry,p.effect_scope,now);
        const auto storm=skills::effects::active_storm_chaser(*p.effect_registry,p.effect_scope,now);
        const auto gain=(mantra&&mantra->kind==hit.kind?mantra->energy:0)+(storm?skills::effects::storm_chaser_energy(*storm,hit):0);
        if(!gain)return;
        if(p.energy_updated)regenerate_energy_locked(p,now-p.energy_updated);
        p.energy_updated=now;gain_energy_locked(p,gain, now);
        p.outbox->enqueue(owner_vitals(p));
    }
