    static std::optional<unsigned> illusionary_armor_locked(const Player& victim,std::uint64_t now){
        if(!victim.effect_registry)return 0;
        const auto entry=victim.effect_registry->newest_skill(victim.effect_scope,33,now,3181);
        if(!entry)return 0;
        const auto plan=skills::effects::illusionary_weaponry(entry->skill,entry->rank);
        if(!plan||entry->kind!=skills::effects::Category::enchantment)return {};
        if(!plan->armor_per_skill)return 0;
        if(!victim.cooldown_authority)return {};
        const auto bar=victim.cooldown_authority->snapshot(victim.effect_scope);
        return bar&&bar->published.at<=now?skills::effects::illusionary_weaponry_armor(*plan,bar->bar):std::nullopt;
    }
    std::optional<combat::Hit> player_weapon_hit_locked(const Player& victim,combat::Actor& actor,double damage,std::uint64_t now)const{
        if(!std::isfinite(damage)||damage<0||damage>16000000)return {};
        if(victim.effect_registry&&victim.effect_registry->newest_skill(victim.effect_scope,1399,now)){
            const auto counter=victim.shield_absorption_hits.value_or(skills::effects::ShieldAbsorption(victim.effect_scope));
            const auto quote=counter.prepare(*victim.effect_registry,victim.effect_scope,counter.last_event()+1,now);
            if(!quote)return {};
            damage=std::max(0.,damage-quote->reduction);
            actor.cumulative_reduction=skills::effects::ShieldAbsorption::receipt(*quote);
        }
        return combat::weapon::apply_resolved(actor,damage,true);
    }
