    bool ignite_explosion_locked(Player& caster,const skills::ranger::IgniteArrowsPlan& plan,unsigned level,
            float x,float y,std::uint16_t plane,std::uint64_t now){
        if(!skills::ranger::valid_ignite_arrows(plan)||!level||level>255)return false;
        const combat::Damage damage{combat::Kind::fire,double(plan.damage),level,431};
        std::vector<skills::effects::Scope> players;
        for(auto&[id,victim]:players_){
            if(!caster.team_token||!victim.team_token||caster.team_token==victim.team_token||!victim.resources||victim.surface.plane!=plane)continue;
            const auto point=healing_position_locked(victim,now);if(!point)return false;
            if(std::hypot(point->x-x,point->z-y)>plan.radius)continue;
            if(!advance_health_locked(victim,now))return false;if(victim.precise_health<=0)continue;
            if(!victim.reviewed_fire_armor)return false;
            auto actor=incoming_spell_actor_locked(victim,{id,victim.effect_scope.generation,combat::Health{victim.precise_health,victim.resources->max_health},std::nullopt,victim.effects,true,{},victim.reviewed_fire_armor},now,true);
            const auto hit=combat::apply(actor,damage,true);if(hit.reason!=combat::Reason::accepted||!prepare_player_reactive_seed_locked(victim,hit,now))return false;
            players.push_back(victim.effect_scope);
        }
        std::vector<skills::effects::Scope> npcs;
        for(auto&[id,live]:npc_combat_){const auto npc=npcs_.find(id);const auto life=live.lifetime();
            if(npc==npcs_.end()||npc->second.plane!=plane||!live.hostile_to_players(life)||std::hypot(npc->second.x-x,npc->second.y-y)>plan.radius)continue;
            advance_npc_conditions_locked(id,live,now);const auto* actor=live.actor(life);
            if(!actor||!actor->damageable||!actor->health||actor->health->current<=0)continue;
            auto proposed=live;if(!preflight_npc_reversal_or_damage_locked(proposed,damage,now))return false;
            npcs.push_back(live.hex_scope());
        }
        for(const auto candidate:players){const auto found=players_.find(candidate.actor);
            if(found==players_.end()||found->second.effect_scope!=candidate||found->second.precise_health<=0)continue;
            auto& victim=found->second;
            auto actor=incoming_spell_actor_locked(victim,{victim.id,victim.effect_scope.generation,
                combat::Health{victim.precise_health,victim.resources->max_health},{},victim.effects,true,{},victim.reviewed_fire_armor},now,true);
            const auto hit=combat::apply(actor,damage,true);
            if(hit.reason!=combat::Reason::accepted||!commit_player_reactive_hit_locked(victim,hit,caster.id,now))
                throw std::logic_error("Ignite Arrows player protection changed during commit");
        }
        for(const auto candidate:npcs){
            const auto live=npc_combat_.find(candidate.actor);const auto npc=npcs_.find(candidate.actor);
            if(live==npc_combat_.end()||npc==npcs_.end()||live->second.hex_scope()!=candidate)continue;
            const auto* current=live->second.actor(live->second.lifetime());
            if(!current||!current->health||current->health->current<=0)continue;
            if(!commit_npc_reversal_or_damage_locked(caster,npc->second,live->second,damage,now))
                throw std::logic_error("Ignite Arrows NPC damage changed during commit");
        }
        return true;
    }
