    std::uint64_t begin_attack_outcome_locked(skills::effects::Scope source,skills::effects::Scope target,std::uint64_t now,
            combat::weapon::AttackDelivery delivery=combat::weapon::AttackDelivery::unknown,unsigned attack_skill=0,bool logical_release=true){
        if(next_attack_outcome_==UINT64_MAX)return 0;
        if(delivery==combat::weapon::AttackDelivery::unknown){
            const auto player=players_.find(source.actor);
            if(player!=players_.end()&&player->second.effect_scope==source&&player->second.ordinary_weapon){
                const auto& weapon=*player->second.ordinary_weapon;
                delivery=combat::weapon::weapon_delivery(weapon.item_type,weapon.caster_weapon);
            }
        }
        auto owner=attack_outcomes_.try_emplace(source,source).first;
        if(!owner->second.release(source,target,next_attack_outcome_,now,delivery))return 0;
        const auto event=next_attack_outcome_++;
        if(!logical_release)return event; // sealed failed dual phase2: physical attempt only
        const auto dual=claim_dagger_dual_release_draft_locked(source,target,attack_skill,event,now);
        if(!dual){
            if(const auto cancelled=owner->second.finish(source,target,event,AttackOutcome::cancelled,now))owner->second.acknowledge(source,*cancelled);
            return 0;
        }
        if(*dual)return event; // second actual hit shares one logical release
        if(!end_weapon_spell_attack_locked(source,now)){
            if(const auto cancelled=owner->second.finish(source,target,event,AttackOutcome::cancelled,now))owner->second.acknowledge(source,*cancelled);
            return 0;
        }
        reserve_dodge_this_attack_locked(source,event,now);
        observe_pet_attack_release_locked(source,target,now);
        return event;
    }
