                if(!actor||!actor->health||!reduction||!plan)return;
                const auto qualified=skills::effects::insidious_parasite_transfer(credit.caster,credit.target,*current_entry,hit,
                    {caster->second.precise_health,caster->second.resources->max_health},*actor->health,*reduction);
                if(!qualified||double(plan->amount)<=*reduction)return;
                if(!commit_reversal_life_steal_transfer_locked(credit.caster,credit.target,plan->amount,hit.at))return;
                if(const auto current=players_.find(credit.caster.actor);current!=players_.end()&&current->second.effect_scope==credit.caster&&current->second.precise_health<=0)
                    kill_locked(current->second,hit.at);
