        player.adrenaline.reset();publish_adrenaline_locked(player);
        player.melee_skill_until=0;
        cancel_ordinary_locked(player,combat::weapon::Cancel::invalid_state);
        player.dagger_chain.clear();
        player.iron_palm_wire_expiries.clear();
        stop_npc_approach_locked(player,now);cancel_npc_interaction(player);
        if(player.turn_updated&&now>=player.turn_updated)
            player.heading=std::remainder(player.heading+player.turn_rate*float(now-player.turn_updated)/1000.f,6.283185307f);
        player.turn_rate=0;player.turn_updated=now;player.movement_multiplier=1.f;player.ward_click_published_factor=player.ward_steering_published_factor=1.f;player.movement_effects={};player.movement_effect_clock=now;player.knocked_down_until=0;
        player.precise_health=0;player.resources->health=0;player.effects|=0x10;
        dispatch_bundle_releases_locked(now);
        clear_insidious_caster_locked(player.effect_scope,now);
        clear_parasitic_caster_locked(player.effect_scope,now);
        // This charged self effect has no expiry timer. Death must retire its
        // owned status and charge ledger rather than leave a permanent bonus
