        if(player.effect_registry)for(const auto& entry:player.effect_registry->active(player.effect_scope,now))
            if(entry.kind==skills::effects::Category::glyph||(entry.kind==skills::effects::Category::stance&&entry.skill!=345&&entry.skill!=3204)||entry.skill==361||entry.skill==362||entry.skill==363||entry.skill==374){
                player.effect_registry->remove(player.effect_scope,entry.instance);
                for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(player.id,entry.instance)});
            }
        if(player.effect_registry)player.effect_registry->take_applications(player.effect_scope);
        clear_life_drains_locked(player.effect_scope,now);
        clear_health_effects_locked(player,now);clear_conditions_locked(player,now);
