            int well_pips=0;
            bool well_strips=false;
            const double sample=static_cast<double>(starts)+.5;
            for(const auto& segment:well_exposure)if(segment.begins<=sample&&sample<segment.ends){
                well_pips=segment.effect.health_pips;
                well_strips=segment.effect.strip_enchantments;
                break;
            }
            if(well_strips)strip_well_enchantments_locked(player,starts);
            const auto external=player.conditions.degeneration_pips(starts)+player.health_regeneration->pips(starts)+survival_pips_locked(player,starts)+well_pips;
            if(player.passive_recovery&&(external<0||player.precise_health<=0))player.passive_recovery->inhibit(starts);
            auto ends=*std::upper_bound(boundaries.begin(),boundaries.end(),starts);
            unsigned automatic=0;
            if(player.passive_recovery){
                automatic=player.precise_health>0?player.passive_recovery->pips(starts):0;
                const auto segments=player.passive_recovery->segments(now);
                if(!segments.empty())ends=std::min(ends,segments.front().end);
            }
            const auto net_pips=std::clamp(external+static_cast<int>(automatic),-10,10);
            ends=health_crossing_end(starts,ends,player.precise_health,net_pips);
            // Settle Energy while the actor is still alive for this Health
            // segment. Ordinary regeneration and modifier-owned Energy both
            // belong before degeneration or an expiry reaction can kill it.
            // Advance the same cursor so later resource settlement cannot
            // award this interval twice.
            if(ends>=player.energy_updated){
                const auto step=regenerate_energy_locked(player,ends-player.energy_updated);player.energy_updated=ends;
                if(step.changed)player.outbox->enqueue(owner_vitals(player));
            }
            const auto before_regeneration=player.precise_health;
            auto integrated=before_regeneration;
            const auto virtual_capacity=player.resources->max_health+static_cast<unsigned>(std::ceil(player.deep_wound.debt));
            if(!player.health_regeneration->advance(player.effect_scope,ends,integrated,virtual_capacity,
                    player.conditions.degeneration_pips(starts)+survival_pips_locked(player,starts)+well_pips+automatic))return false;
            player.deep_wound.regeneration(player.precise_health,integrated-before_regeneration);
            if(combat::health_timing::zero_residue(player.precise_health,net_pips))
                player.deep_wound.regeneration(player.precise_health,-player.precise_health);
            sync_deep_wound_locked(player,ends);
            settle_conditional_stance_locked(player,ends);
            // Reactions can settle another seeded party member, which can in
