            boundaries.insert(boundaries.end(),added_boundaries.begin(),added_boundaries.end());std::sort(boundaries.begin(),boundaries.end());
            if(player.passive_recovery){player.passive_recovery->commit(ends);if(external<0||player.precise_health<=0)player.passive_recovery->inhibit(ends);}
