        std::vector<std::uint32_t> expired;
        for(const auto& [id,effect]:player.health_effects)if(effect.expires&&*effect.expires<=now)expired.push_back(id);
        for(auto id:expired)remove_health_effect_locked(player,id,now);
        std::vector<combat::conditions::Kind> expired_conditions;
        for(const auto& [kind,effect]:player.condition_effects)if(*effect.expires<=now)expired_conditions.push_back(kind);
