    // Trusted successful-interrupt controller entry point. Contact producers
    // must still prove hit/range/protection before invoking this transaction.
    bool interrupt_npc_skill_with_disable(skills::effects::Scope owner,const combat::npcs::control::Token& token,
            const combat::weapon::InterruptDisablePlan& plan,std::uint64_t now){
        std::lock_guard lock(mutex_);const auto found=npc_combat_.find(owner.actor);
        if(found==npc_combat_.end()||found->second.hex_scope()!=owner)return false;
        const auto old=attack_interrupt_disables_.find(owner);
        const auto proposed=combat::npcs::prepare_attack_interrupt(found->second,found->second.lifetime(),token,
            old==attack_interrupt_disables_.end()?combat::weapon::AttackInterruptDisables(owner):old->second,plan,now);
        if(!proposed)return false;
        attack_interrupt_disables_.insert_or_assign(owner,proposed->disables);found->second=proposed->actor;
        Packet stopped;u16(stopped,158);u32(stopped,59);u32(stopped,owner.actor);u32(stopped,0);
        for(auto& [id,peer]:players_)if(peer.npc_publication_ready&&(!npc_visibility_radius_||peer.published_npcs.contains(owner.actor)))peer.outbox->enqueue({stopped});
        return true;
    }
