    bool complete_npc_action(const combat::npcs::control::Token& token,std::uint64_t now){
        std::lock_guard lock(mutex_);
        // A premature completion must not settle the whole instance backward
        // before the action authority gets a chance to reject it.
        if(now<token.completes)return false;
        if(const auto pending=controlled_spirit_attacks_.find(token.actor.actor);
           pending!=controlled_spirit_attacks_.end()&&pending->second.first==token)return false;
        if(const auto typed=npc_bonds_casts_.find(token.actor.actor);typed!=npc_bonds_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_watchful_casts_.find(token.actor.actor);typed!=npc_watchful_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_phantasm_casts_.find(token.actor.actor);typed!=npc_phantasm_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_self_enchantment_casts_.find(token.actor.actor);typed!=npc_self_enchantment_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_friendly_heals_.find(token.actor.actor);typed!=npc_friendly_heals_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_reversal_casts_.find(token.actor.actor);typed!=npc_reversal_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_imbue_casts_.find(token.actor.actor);typed!=npc_imbue_casts_.end()&&typed->second.token==token)return false;
        if(const auto typed=npc_immediate_ai_.find(token.actor.actor);typed!=npc_immediate_ai_.end()&&
           typed->second.pending&&typed->second.pending->token==token)return false;
        settle_damage_fields_locked(now);const auto found=npc_combat_.find(token.actor.actor);
        if(found==npc_combat_.end()||found->second.hex_scope()!=token.actor)return false;
        advance_npc_conditions_locked(token.actor.actor,found->second,now);
        if(!complete_npc_ether_terminal_locked(found->second,token,now))return false;
        if(token.kind==combat::npcs::control::Action::spell&&token.skill){
            const auto* row=skills::find_skill(token.skill->skill);
            if(row&&skills::effects::is_spell(*row)&&!succor_npc_spell_completed_locked(token,now))return false;
        }
        if(token.kind==combat::npcs::control::Action::attack&&token.skill){
            const auto row=skills::find_skill(token.skill->skill);
            if(row&&row->type==14){
                const auto active=found->second.newest_stance(found->second.lifetime(),now);
                if(active&&active->skill==1728){
                    if(!found->second.remove_stance(found->second.lifetime(),active->instance,now))
                        throw std::logic_error("completed NPC attack cannot end Heket stance");
                    const auto packet=health_effect_remove(token.actor.actor,active->instance);
                    for(auto&[id,peer]:players_)if(peer.npc_publication_ready&&(!npc_visibility_radius_||peer.published_npcs.contains(token.actor.actor)))
                        peer.outbox->enqueue({packet});
                }
            }
        }
        return true;
    }
