    bool gale(skills::effects::Scope source,skills::effects::Scope target,unsigned rank,std::optional<double> roll,std::uint64_t now){
        if(rank>20||now>UINT64_MAX-2000||(rank<=4&&!roll)||(roll&&(!std::isfinite(*roll)||*roll<0||*roll>=1)))return false;
        std::lock_guard lock(mutex_);settle_damage_fields_locked(now);
        const auto caster=players_.find(source.actor);if(caster==players_.end()||caster->second.effect_scope!=source||
            !advance_resource_event_locked(caster->second,now)||caster->second.precise_health<=0||caster->second.knocked_down_until>now)return false;
        const auto publish=[&]{if(const auto body=skills::particles::targeted_body_2022(target.actor,source.actor,162))
            for(auto&[id,peer]:players_)peer.outbox->enqueue({*body});};
        const auto player=players_.find(target.actor);
        if(player!=players_.end()){
            auto& victim=player->second;if(victim.effect_scope!=target||!advance_health_locked(victim,now))return false;
            const auto state=ordinary_snapshot_locked(caster->second,victim,now);
            if(!state.alive||!state.target_alive||!state.hostile||!state.line_of_sight||state.distance>1248)return false;
            if(rank<=4&&*roll<.5)return true;
            if(victim.knocked_down_until>now)return true;
            if(victim.control_epoch==UINT64_MAX)return false;
            publish();
            if(!knockdown_player_locked(victim,2000,now))throw std::logic_error("validated Gale knockdown failed");
            return true;
        }
        auto body=npcs_.find(target.actor);auto npc=npc_combat_.find(target.actor);
        if(body==npcs_.end()||npc==npc_combat_.end()||npc->second.hex_scope()!=target)return false;
        advance_npc_conditions_locked(target.actor,npc->second,now);refresh_npc_movement_locked(target.actor,now);
        body=npcs_.find(target.actor);npc=npc_combat_.find(target.actor);
        if(body==npcs_.end()||npc==npc_combat_.end()||npc->second.hex_scope()!=target)return false;
        const auto state=ordinary_npc_snapshot_locked(caster->second,body->second,npc->second,now);
        if(!state.alive||!state.target_alive||!state.hostile||!state.line_of_sight||state.distance>1248||
           !npc->second.knockdown_allowed(npc->second.lifetime(),now).has_value())return false;
        if(rank<=4&&*roll<.5)return true;
        using K=combat::npcs::control::Knockdown;
        // Preflight on a value copy before publishing the captured body->KD
        // order. Unknown/exhausted actors cannot leak a success particle.
        auto proposal=npc->second;const auto eligible=proposal.knock_down(proposal.lifetime(),now,2000);
        if(eligible==K::immune||eligible==K::already_down)return true;
        if(eligible!=K::accepted)return false;
        publish();
        if(knockdown_npc_locked(target,2000,now)!=K::accepted)throw std::logic_error("validated Gale NPC knockdown failed");
        return true;
    }
