            advance_movement_effects_locked(p,now);
            p.movement_effects.remove(effect,now);if(p.health_regeneration)p.health_regeneration->remove(scope,effect);p.health_effects.erase(effect);
            for(auto&[id,peer]:players_)peer.outbox->enqueue({health_effect_remove(p.id,effect)});
