        for(const auto& event:plan->cooldowns){history.push_back(event);if(history.size()>4096)history.pop_front();}
        skills::effects::CopyRestorationReceipt receipt(owner,std::move(plan->cooldowns));
        player.cooldown_authority=std::move(plan->authority);player.adrenaline=std::move(pools);player.copy_restoration_cooldowns=std::move(history);
        if(change.before!=change.after)player.local_cooldown_snapshot_ready=false;
