            if(n==npcs_.end()||live==npc_combat_.end()||(attack&&attack->knockdown_on_hit&&!live->second.knockdown_allowed(live->second.lifetime(),now).has_value())||(skill!=394&&skill!=408&&skill!=399&&!npc_weapon_armor_locked(live->second,damage_weapon,now)))return false;
