        if(source==players_.end()||source->second.effect_scope!=scope||!source->second.resources||!level||level>255||javelin_projectiles_.size()>=4096||!advance_health_locked(source->second,now)||source->second.precise_health<=0||source->second.knocked_down_until>now)return false;
        auto& caster=source->second;const auto origin=healing_position_locked(caster,now);if(!origin)return false;
