    bool projectile_target_valid(skills::effects::Scope scope,std::uint32_t target,float range,std::uint64_t now,bool allow_knockdown=false,bool allow_dead_target=false)const{
        if(!std::isfinite(range)||range<=0||range>1248)return false;
        std::lock_guard lock(mutex_);const auto a=players_.find(scope.actor),b=players_.find(target);
        if(a!=players_.end()&&b==players_.end()){
            const auto n=npcs_.find(target);const auto combat=npc_combat_.find(target);
            if(n==npcs_.end()||combat==npc_combat_.end()||a->second.effect_scope!=scope||
               !a->second.resources||a->second.precise_health<=0||(!allow_knockdown&&a->second.knocked_down_until>now)||
               a->second.surface.plane!=n->second.plane)return false;
            const auto& live=combat->second;const auto* actor=live.actor(live.lifetime());
            if(!live.hostile_to_players(live.lifetime())||!actor->damageable||!actor->health||(actor->health->current<=0&&!allow_dead_target))return false;
            const auto point=healing_position_locked(a->second,now);
            return point&&std::hypot(point->x-n->second.x,point->z-n->second.y)<=range;
        }
        if(a==players_.end()||b==players_.end()||a->second.effect_scope!=scope||!a->second.team_token||!b->second.team_token||a->second.team_token==b->second.team_token||!a->second.resources||!b->second.resources||a->second.precise_health<=0||(b->second.precise_health<=0&&!allow_dead_target)||(!allow_knockdown&&a->second.knocked_down_until>now)||a->second.surface.plane!=b->second.surface.plane)return false;
        const auto origin=healing_position_locked(a->second,now),destination=healing_position_locked(b->second,now);
        return origin&&destination&&std::hypot(origin->x-destination->x,origin->z-destination->z)<=range;
    }
    bool shout_target_valid(skills::effects::Scope scope,std::uint32_t target,float range,std::uint64_t now)const{
        return projectile_target_valid(scope,target,range,now,true);
    }
    bool launch_disrupting_dagger(skills::effects::Scope scope,skills::effects::Scope target,
            const skills::effects::DisruptingDaggerPlan& plan,unsigned level,std::uint64_t now,
            std::vector<Packet>* completion=nullptr){
        if(completion)completion->clear();
        const auto canonical=skills::effects::disrupting_dagger(plan.rank);
        if(!canonical||*canonical!=plan||!level||level>255)return false;
        std::lock_guard lock(mutex_);
        const auto a=players_.find(scope.actor);
        if(a==players_.end()||a->second.effect_scope!=scope||!a->second.team_token||
           !a->second.resources||a->second.precise_health<=0||
           a->second.knocked_down_until>now||disrupting_daggers_.size()>=4096)return false;
        const auto origin=healing_position_locked(a->second,now);
        const auto victim=stone_target_locked(a->second,target,now);
        if(!origin||!victim||victim->plane!=a->second.surface.plane||
           std::hypot(origin->x-victim->point.x,origin->z-victim->point.z)>plan.range)return false;
        double vx=0,vy=0;
        if(const auto b=players_.find(target.actor);b!=players_.end()&&now<=UINT64_MAX-10)
            if(const auto future=healing_position_locked(b->second,now+10)){
                vx=(future->x-victim->point.x)*100;vy=(future->z-victim->point.z)*100;
            }
        const auto aim=projectiles::intercept(projectile_policy_,origin->x,origin->z,
            victim->point.x,victim->point.z,vx,vy);
        if(!aim||now>UINT64_MAX-aim->flight_ms)return false;
        if(navigation_){const auto line=layered_->trace(a->second.surface,*origin,victim->point);
            if(!line||line->plane!=victim->plane)return false;}
        if(!advance_health_locked(a->second,now)||a->second.precise_health<=0)return false;
        disrupting_daggers_.push_back({scope,target,plan,level,aim->x,aim->y,
            victim->plane,now+aim->flight_ms});
        const auto launch=skills::particles::spell_projectile_launch_2022(
            scope.actor,aim->x,aim->y,victim->plane,float(aim->flight_ms)/1000.f,571);
        if(completion)completion->push_back(launch);
        else for(auto& [id,peer]:players_)peer.outbox->enqueue({launch});
        if(a->second.passive_recovery)a->second.passive_recovery->record(recovery::Event::target_enemy_spell_or_signet,now);
        if(const auto b=players_.find(target.actor);b!=players_.end()&&b->second.passive_recovery)
            b->second.passive_recovery->record(recovery::Event::targeted_by_enemy_spell_or_signet,now);
        return true;
    }
    bool launch_projectile(skills::effects::Scope scope,std::uint32_t target,const skills::effects::EarthProjectilePlan& plan,unsigned level,std::uint64_t now){
        if(!skills::effects::valid_earth_projectile(plan)||!level||level>255)return false;
        std::lock_guard lock(mutex_);const auto a=players_.find(scope.actor),b=players_.find(target);
        if(a==players_.end()||b==players_.end()||a->second.effect_scope!=scope||!a->second.team_token||!b->second.team_token||a->second.team_token==b->second.team_token||!a->second.resources||!b->second.resources||a->second.precise_health<=0||b->second.precise_health<=0||a->second.knocked_down_until>now||a->second.surface.plane!=b->second.surface.plane||!b->second.reviewed_earth_armor||projectiles_.size()>=4096)return false;
        const auto origin=healing_position_locked(a->second,now),destination=healing_position_locked(b->second,now);if(!origin||!destination||std::hypot(origin->x-destination->x,origin->z-destination->z)>plan.range)return false;
        // Fire-time position/velocity leading; projectile destination is fixed,
        // so changing movement after release can dodge rather than homing.
        const auto future=now<=UINT64_MAX-10?healing_position_locked(b->second,now+10):std::nullopt;
        const double vx=future?(future->x-destination->x)*100:0,vy=future?(future->z-destination->z)*100:0;
        const auto aim=projectiles::intercept(projectile_policy_,origin->x,origin->z,destination->x,destination->z,vx,vy);if(!aim||now>UINT64_MAX-aim->flight_ms)return false;
        if(navigation_){const auto line=layered_->trace(a->second.surface,*origin,*destination);if(!line||line->plane!=b->second.surface.plane)return false;}
        if(!advance_health_locked(a->second,now)||!advance_health_locked(b->second,now))return false;
        if(a->second.passive_recovery)a->second.passive_recovery->record(recovery::Event::target_enemy_spell_or_signet,now);
        if(b->second.passive_recovery)b->second.passive_recovery->record(recovery::Event::targeted_by_enemy_spell_or_signet,now);
        projectiles_.push_back({scope,b->second.effect_scope,plan,level,aim->x,aim->y,static_cast<std::uint16_t>(b->second.surface.plane),now+aim->flight_ms});
        return true;
    }
