    bool blindness(skills::effects::Scope scope,skills::effects::Scope target,const skills::effects::BlindnessPlan& plan,std::uint64_t now){
        if(!skills::effects::valid_blindness(plan)||now>UINT64_MAX-plan.duration)return false;
        std::lock_guard lock(mutex_);
        auto perform_condition_batch=[&]()->bool{
            const auto a=players_.find(scope.actor);
            if(a==players_.end()||a->second.effect_scope!=scope||!a->second.resources||a->second.precise_health<=0||
               a->second.knocked_down_until>now||now<a->second.health_updated)return false;
            auto& source=a->second;const auto origin=healing_position_locked(source,now);if(!origin)return false;
            navigation::Point center{};unsigned plane=0;
            const auto b=players_.find(target.actor);
            if(b!=players_.end()){
                const auto& p=b->second;if(p.effect_scope!=target||!p.resources||p.precise_health<=0||!source.team_token||!p.team_token||p.team_token==source.team_token)return false;
                const auto position=healing_position_locked(p,now);if(!position)return false;center=*position;plane=p.surface.plane;
            }else{
                const auto n=npcs_.find(target.actor);const auto live=npc_combat_.find(target.actor);
                if(n==npcs_.end()||live==npc_combat_.end()||live->second.hex_scope()!=target||!live->second.hostile_to_players(live->second.lifetime()))return false;
                refresh_npc_movement_locked(target.actor,now);center={n->second.x,n->second.y};plane=n->second.plane;
            }
            if(source.surface.plane!=plane||std::hypot(origin->x-center.x,origin->z-center.z)>plan.range)return false;
            if(navigation_){const auto line=layered_->trace(source.surface,*origin,center);if(!line||line->plane!=plane)return false;}
            struct Candidate{Player* player;combat::conditions::State conditions;};std::vector<Candidate> players;
            std::vector<std::pair<std::uint32_t,combat::npcs::LiveActor>> npcs;
            if(!advance_health_locked(source,now)||source.precise_health<=0)return false;
            bool selected=false;
            for(auto& [id,p]:players_){
                const bool drawback=id==scope.actor&&plan.blind_caster;
                if(!drawback){
                    if(!source.team_token||!p.team_token||source.team_token==p.team_token||p.surface.plane!=plane||(!plan.radius&&id!=target.actor))continue;
                    const auto pos=healing_position_locked(p,now);if(!pos)return false;
                    if(plan.radius&&std::hypot(pos->x-center.x,pos->z-center.z)>plan.radius)continue;
                }
                if(!p.resources||p.precise_health<=0)continue;
                if(now<p.health_updated||p.next_health_effect>UINT32_MAX||!advance_health_locked(p,now))return false;
                if(p.precise_health<=0)continue;
                auto conditions=p.conditions;if(!conditions.apply(combat::conditions::Kind::blind,scope.actor,now,plan.duration))return false;
                players.push_back({&p,std::move(conditions)});selected|=id==target.actor;
            }
            for(auto& [id,live]:npc_combat_){
                const auto placement=npcs_.find(id);const auto life=live.lifetime();
                if(placement==npcs_.end()||!live.hostile_to_players(life)||placement->second.plane!=plane||(!plan.radius&&id!=target.actor))continue;
                refresh_npc_movement_locked(id,now);
                if(plan.radius&&std::hypot(placement->second.x-center.x,placement->second.y-center.z)>plan.radius)continue;
                if(now<live.health_clock(life).value_or(now))return false;
                advance_npc_conditions_locked(id,live,now);const auto actor=live.actor(life);
                if(!actor||!actor->health||actor->health->current<=0)continue;
                auto proposed=live;if(proposed.allows_conditions(life)&&!proposed.apply_condition(life,combat::conditions::Kind::blind,scope.actor,now,plan.duration))return false;
                npcs.emplace_back(id,std::move(proposed));selected|=id==target.actor;
            }
            if(!selected)return false; // Never apply Midnight's drawback after losing its selected victim.
            const auto visual=[&](unsigned id){
                if(plan.skill==58){if(id!=scope.actor){const auto packet=skills::particles::midnight_target_2022(id,scope.actor);for(auto&[peer_id,peer]:players_)peer.outbox->enqueue({packet});}}
                else publish_target_body_locked(id,plan.skill,scope.actor);
        };
        if(source.passive_recovery)source.passive_recovery->record(recovery::Event::target_enemy_spell_or_signet,now);
        for(auto& candidate:players){auto& p=*candidate.player;
            if(p.id!=scope.actor&&p.passive_recovery)p.passive_recovery->record(recovery::Event::targeted_by_enemy_spell_or_signet,now);
            commit_conditions_locked(p,candidate.conditions,{combat::conditions::Kind::blind},now);visual(p.id);
        }
        for(auto& [id,proposed]:npcs){npc_combat_.at(id)=std::move(proposed);auto& live=npc_combat_.at(id);const auto life=live.lifetime();
            npc_condition_credit_[{id,scope.actor}]={{instance_scope_,id,life.actor_generation},scope};
            publish_npc_fragility_locked(id,live);
            commit_applications_locked(live.hex_scope(),now);
            for(auto&[peer_id,peer]:players_)peer.outbox->enqueue({emotes::effects_2022(id,live.actor(life)->effects)});visual(id);
        }
        return true;
        };
        const bool accepted=perform_condition_batch();
        dispatch_fevered_boundary_locked(now);
        return accepted;
    }
