    std::optional<std::uint64_t> attack_duration(skills::effects::Scope scope,std::uint64_t base,std::uint64_t now,bool skill_use=false)const{
        std::lock_guard lock(mutex_);const auto p=players_.find(scope.actor);
        if(p==players_.end()){
            const auto npc=npc_combat_.find(scope.actor);
            if(npc==npc_combat_.end())return {};
            const auto life=npc->second.lifetime();
            if(scope!=skills::effects::Scope{instance_scope_,scope.actor,life.actor_generation})return {};
            return npc->second.attack_duration(life,base,now);
        }
        if(p->second.effect_scope!=scope||!p->second.effect_registry)return {};
        const auto effects=p->second.effect_registry->active(scope,now);
        const auto dwarven=dwarven_bonuses_locked(p->second,now);if(!dwarven)return {};
        return skills::effects::reviewed_attack_duration(base,dwarven->haste||skills::effects::tiger_stance_active(effects,now)||skills::effects::hekets_rampage_active(effects,now)||(!skill_use&&skills::effects::berserker_stance_active(effects,now))||skills::effects::frenzy_active(effects,now)||skills::effects::flurry_active(effects,now)||skills::effects::lightning_reflexes_active(effects,now)||skills::effects::flail_active(effects,now),skills::effects::faintheartedness_active(effects,now),skills::effects::bestial_fury_active(effects,now));
    }
    bool i_will_survive(skills::effects::Scope owner,const skills::effects::SurvivalPlan& plan,std::uint64_t now){
        const auto expected=skills::effects::i_will_survive(plan.rank);
        if(!expected||*expected!=plan||now>UINT64_MAX-plan.duration)return false;
        std::lock_guard lock(mutex_);const auto found=players_.find(owner.actor);
        if(found==players_.end()||found->second.effect_scope!=owner)return false;auto& p=found->second;
        // Shouts are allowed while another action or knockdown is active.
        if(!advance_resource_event_locked(p,now)||p.precise_health<=0||p.next_health_effect>UINT32_MAX)return false;
        const auto id=static_cast<std::uint32_t>(p.next_health_effect);
        const skills::effects::Entry entry{id,owner.actor,368,plan.rank,skills::effects::Category::other,now,now+plan.duration};
        auto registry=*p.effect_registry;auto timers=*p.health_regeneration;
        const auto applied=registry.apply(owner,entry,skills::effects::Replace::same_skill);if(!applied.accepted)return false;
        for(const auto& old:applied.removed)timers.remove(owner,old.instance);
        if(!timers.apply(owner,{id,owner.actor,368,0,now,*entry.expires}))return false;
        *p.effect_registry=std::move(registry);*p.health_regeneration=std::move(timers);++p.next_health_effect;
        std::vector<Packet> packets;
        for(const auto& old:applied.removed){p.health_effects.erase(old.instance);packets.push_back(health_effect_remove(owner.actor,old.instance));}
        p.health_effects.emplace(id,entry);
        packets.push_back(combat::detail::integer(21,owner.actor,627));packets.push_back(health_effect_add(entry,owner.actor,now));
        for(auto& [peer_id,peer]:players_)peer.outbox->enqueue(packets);
        commit_applications_locked(owner,now);publish_status_locked(p,now);return true;
    }
    bool dodge_this(skills::effects::Scope owner,
            const skills::effects::DodgeThisPlan& plan,std::uint64_t now){
        const auto expected=skills::effects::dodge_this(plan.rank);
        if(!expected||expected->skill!=plan.skill||expected->bonus_damage!=plan.bonus_damage||
           expected->duration_ms!=plan.duration_ms||now>UINT64_MAX-plan.duration_ms)return false;
        std::lock_guard lock(mutex_);
        const auto found=players_.find(owner.actor);
        if(found==players_.end()||found->second.effect_scope!=owner)return false;
        auto& p=found->second;
        if(!p.effect_registry||!p.health_regeneration||!advance_resource_event_locked(p,now)||
           p.precise_health<=0||p.next_health_effect>UINT32_MAX)return false;
        const auto effect=static_cast<std::uint32_t>(p.next_health_effect);
        const skills::effects::Entry entry{effect,owner.actor,2354,plan.rank,
            skills::effects::Category::other,now,now+plan.duration_ms};
        auto registry=*p.effect_registry;auto timers=*p.health_regeneration;
        const auto applied=registry.apply(owner,entry,skills::effects::Replace::same_skill);
        if(!applied.accepted)return false;
        for(const auto& old:applied.removed)timers.remove(owner,old.instance);
        if(!timers.apply(owner,{effect,owner.actor,2354,0,now,*entry.expires}))return false;
        *p.effect_registry=std::move(registry);*p.health_regeneration=std::move(timers);
        ++p.next_health_effect;
        std::vector<Packet> packets;
        for(const auto& old:applied.removed){
            p.health_effects.erase(old.instance);
            packets.push_back(health_effect_remove(owner.actor,old.instance));
        }
        p.health_effects.insert_or_assign(effect,entry);
        dodge_this_effects_.insert_or_assign(owner,OwnedDodge{effect,plan.bonus_damage});
        packets.push_back(health_effect_add(entry,owner.actor,now));
        for(auto& [peer_id,peer]:players_)peer.outbox->enqueue(packets);
        commit_applications_locked(owner,now);publish_status_locked(p,now);return true;
    }
