    // Trusted completed-cast producer. The ordinary client gateway stays
    // gated until every weapon contact can consume these owned charges.
    bool apply_signet_strength(skills::effects::Scope owner,
            const skills::effects::SignetStrengthPlan& plan,std::uint64_t now){
        if(skills::effects::signet_strength(plan.rank)!=plan)return false;
        std::lock_guard lock(mutex_);
        const auto found=players_.find(owner.actor);
        if(found==players_.end()||found->second.effect_scope!=owner)return false;
        auto& p=found->second;
        if(!p.effect_registry||!p.resources||p.next_health_effect>UINT32_MAX||
           !advance_resource_event_locked(p,now)||p.precise_health<=0||
           p.knocked_down_until>now)return false;
        const auto effect=static_cast<std::uint32_t>(p.next_health_effect);
        const skills::effects::Entry entry{effect,owner.actor,944,plan.rank,
            skills::effects::Category::other,now,std::nullopt};
        auto registry=*p.effect_registry;
        const auto applied=registry.apply(owner,entry,skills::effects::Replace::same_skill);
        if(!applied.accepted)return false;
        *p.effect_registry=std::move(registry);
        ++p.next_health_effect;
        std::vector<Packet> packets;
        for(const auto& old:applied.removed){
            p.health_effects.erase(old.instance);
            packets.push_back(health_effect_remove(owner.actor,old.instance));
        }
        p.health_effects.insert_or_assign(effect,entry);
        signet_strength_charges_.insert_or_assign(owner,
            skills::effects::StrengthCharges{owner,effect,plan.charges});
        packets.push_back(combat::detail::integer(21,owner.actor,1028));
        Packet status;u16(status,64);u32(status,owner.actor);u32(status,0);
        u16(status,944);u32(status,plan.rank);u32(status,effect);
        packets.push_back(std::move(status));
        for(auto& [peer_id,peer]:players_)peer.outbox->enqueue(packets);
        commit_applications_locked(owner,now);publish_status_locked(p,now);
        return true;
    }
    std::optional<skills::effects::StrengthCharges> signet_strength_snapshot(
            skills::effects::Scope owner,std::uint64_t now)const{
        std::lock_guard lock(mutex_);
        const auto found=players_.find(owner.actor);
        const auto charges=signet_strength_charges_.find(owner);
        if(found==players_.end()||found->second.effect_scope!=owner||
           !found->second.effect_registry||charges==signet_strength_charges_.end())return {};
        const auto active=found->second.effect_registry->newest_skill(owner,944,now);
        if(!active||active->instance!=charges->second.effect||
           !skills::effects::signet_strength(active->rank)||
           charges->second.remaining>skills::effects::signet_strength(active->rank)->charges)return {};
        return charges->second;
    }
