    std::optional<skills::effects::ResourceGainOutcome> resource_gain(skills::effects::Scope scope,
            skills::effects::Scope target,const skills::effects::ResourceGainPlan& plan,std::uint64_t now){
        if(!skills::effects::valid_resource_gain(plan))return {};
        std::lock_guard lock(mutex_);const auto caster=players_.find(scope.actor);
        if(caster==players_.end()||caster->second.effect_scope!=scope||!caster->second.resources||
           caster->second.precise_health<=0||(!skills::effects::gain_is_shout(plan)&&caster->second.knocked_down_until>now)||
           now<caster->second.health_updated||now<caster->second.energy_updated)return {};
        auto& source=caster->second;
        // Reject a future or retired target before settling the source. Lookups
        // below are repeated after settlement, which can retire linked actors.
        if(plan.skill==1141){
            const auto player=players_.find(target.actor);
            if(player!=players_.end()){
                if(player->second.effect_scope!=target||now<player->second.health_updated)return {};
            }else{
                const auto npc=npc_combat_.find(target.actor);if(npc==npc_combat_.end())return {};
                const auto life=npc->second.lifetime();
                if(target!=skills::effects::Scope{instance_scope_,target.actor,life.actor_generation}||
                   now<npc->second.health_clock(life).value_or(now))return {};
            }
        }
        // Settle linked events before observing Victory's target/count: source
        // resource settlement may retire an NPC through a linked Health effect.
        if(skills::effects::gain_is_shout(plan)&&(!advance_resource_event_locked(source,now)||source.precise_health<=0))return {};
        bool health_predicate=false;unsigned count=0;
        if(skills::effects::gain_targets_foe(plan)){
            const auto origin=healing_position_locked(source,now);if(!origin)return {};
            const auto foe=players_.find(target.actor);
            if(foe!=players_.end()){
                auto& victim=foe->second;
                if(victim.effect_scope!=target||!source.team_token||!victim.team_token||source.team_token==victim.team_token||
                   !victim.resources||victim.precise_health<=0||source.surface.plane!=victim.surface.plane||now<victim.health_updated)return {};
                const auto point=healing_position_locked(victim,now);
                if(!point||std::hypot(point->x-origin->x,point->z-origin->z)>plan.range||!advance_health_locked(victim,now)||victim.precise_health<=0)return {};
                health_predicate=2.*victim.precise_health<victim.resources->max_health;count=victim.conditions.count(now);
            }else{
                const auto npc=npcs_.find(target.actor);const auto live=npc_combat_.find(target.actor);
                if(npc==npcs_.end()||live==npc_combat_.end())return {};
                const auto life=live->second.lifetime();
                if(target!=skills::effects::Scope{instance_scope_,target.actor,life.actor_generation}||!live->second.hostile_to_players(life)||source.surface.plane!=npc->second.plane)return {};
                refresh_npc_movement_locked(target.actor,now);
                if(std::hypot(npc->second.x-origin->x,npc->second.y-origin->z)>plan.range)return {};
                if(navigation_&&!skills::effects::gain_is_shout(plan)){const auto line=layered_->trace(source.surface,*origin,{npc->second.x,npc->second.y});if(!line||line->plane!=npc->second.plane)return {};}
                advance_npc_conditions_locked(target.actor,live->second,now);
                const auto actor=live->second.actor(life);
                if(!actor||!actor->health||actor->health->current<=0||!actor->damageable)return {};
                health_predicate=2.*actor->health->current<actor->health->maximum;
                const auto conditions=live->second.condition_snapshot(life);if(!conditions)return {};count=conditions->count(now);
            }
        }else if(target!=scope)return {};
        if(!advance_health_locked(source,now)||source.precise_health<=0)return {};
        const auto prior_energy=mind_wrack_energy_locked(source);
        if(source.energy_updated)regenerate_energy_locked(source,now-source.energy_updated);
        source.energy_updated=now;
        skills::effects::ResourceGainOutcome result;
        result.condition_met=plan.predicate==skills::effects::GainPredicate::foe_conditions?count!=0:plan.predicate==skills::effects::GainPredicate::foe_below_half_health?health_predicate:
            (source.energy_debt||source.resources->energy<plan.energy_threshold);
        if(result.condition_met){
            if(plan.adrenaline&&!adrenaline_gain_forbidden_locked(source,now)&&
               source.adrenaline.gain_halves(25ull*plan.adrenaline*(source.effect_registry?
                   skills::effects::adrenaline_half_rate(*source.effect_registry,source.effect_scope,now):2u),now))
                publish_adrenaline_locked(source);
            result.energy_gained=gain_energy_locked(source,plan.energy*(plan.skill==365?count:1u), now).total();
            if(plan.health){const auto prior_health=source.precise_health;
                health_event_locked(source,plan.health*(plan.skill==365?count:1u),now);result.health_delta=source.precise_health-prior_health;
                if(source.precise_health<=0)kill_locked(source,now);
                else if(result.health_delta)publish_health_locked(source);
            }
        }
        if(prior_energy!=mind_wrack_energy_locked(source))source.outbox->enqueue(owner_vitals(source));
        if(plan.skill==365){const auto body=combat::detail::integer(21,scope.actor,624);for(auto& [id,peer]:players_)peer.outbox->enqueue({body});}
        return result;
    }
