        player->second.quest_kills.swap(objectives);next_quest_actor_=next_id;next_actor_generation_=generation;
        if(corpse_trainer)player->second.quest_corpses.swap(corpse_objectives);
        if(escort_participants)player->second.quest_escorts.swap(escort_objectives);
