    std::pair<float, float> position(std::uint32_t id, std::uint64_t now) const {
        std::lock_guard lock(mutex_);
        auto it = players_.find(id);
        if (it == players_.end()) throw std::runtime_error("world player is not joined");
        const auto& player = it->second;
        if(northlands_overdue_locked(now))return {player.x,player.y};
        if (!player.moving) return {player.x, player.y};
        if (now <= player.started) return {player.sx, player.sy};
        if (now >= player.ends) return {player.tx, player.ty};
        const auto projected=click_leg_projection_locked(player,now);
        if(!projected)throw std::runtime_error("player route projection unavailable");
        return {static_cast<float>(projected->x),static_cast<float>(projected->y)};
    }
