        retire_splinter_scope_locked(leaving_scope);attack_outcomes_.erase(leaving_scope);ordinary_scythe_policies_followon_.erase(leaving_scope);ordinary_dagger_policies_followon_.erase(leaving_scope);ordinary_dagger_seconds_followon_.erase(leaving_scope);charged_weapon_spells_.erase(leaving_scope);
